using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class TurnRiderPalms {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();File.Copy(d.gameObject.scene.path,"outputs/chapter45-detailed-design-2026-10-03/scene-recovery/Jamsil-before-palms-over-grips.unity",false);var poses=d.hazards.Select(h=>h.body!=null?h.body.GetComponentInChildren<Chapter45RiderPose>(true):null).Where(p=>p!=null).ToArray();foreach(var p in poses){var leftAxis=(p.leftHand.position-p.leftForearm.position).normalized;var rightAxis=(p.rightHand.position-p.rightForearm.position).normalized;p.leftGrip.rotation=Quaternion.AngleAxis(180,leftAxis)*p.leftGrip.rotation;p.rightGrip.rotation=Quaternion.AngleAxis(180,rightAxis)*p.rightGrip.rotation;p.ApplyPose();}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);return new{riders=poses.Length,reason="Place palms over the handlebars instead of facing upward; keep wrist contact locations and original hazard body."};}}
